"""Campaign compiler, typed replay, filtering, and state preparation.

This module is the offline pipeline:

1. compile the campaign configuration into typed model objects;
2. compile one plan per entry (module order, declaration order, symbolic
   harness slots, ``bad_input`` flag and reserved identifier count);
3. recover each recorded KTEST strictly against that harness;
4. evaluate the entry predicate and every composed filter application, and
   check the flag attestation;
5. prepare the deterministic minimum state preamble;
6. assemble the canonical corpus, where a model result is only a witness.
"""

from collections import deque

from eywa import wire
from eywa.ast import (BINOPS, Alias, Array, Binop, Bool, Char, Const, Enum,
                      Field, Forall, Index, Int, Match, Not, Predicate, String,
                      Struct, Type, Var, Void, canonical_op)
from eywa.composer import DependencyGraph
from eywa.oracles import HarnessLayout, InventoryError
from eywa.regex import compile_pattern
from eywa.run import Corpus, corpus_key
from eywa.state import MachineGraph

__all__ = ['execute', 'Campaign', 'ConfigError']

INVALID_TEST = 'INVALID_TEST'
FILTERED = 'FILTERED'
UNREACHABLE = 'UNREACHABLE'
READY = 'READY'
DUPLICATE = 'DUPLICATE'
_EMPTY_MASK = b''


class ConfigError(Exception):
    """A campaign configuration that cannot be compiled."""


class TypeTable(object):
    """Named type definitions, resolved lazily and canonicalised per name."""

    __slots__ = ('definitions', 'cache')

    def __init__(self, definitions):
        table = {}
        for item in definitions:
            table[item['name']] = item
        self.definitions = table
        self.cache = {}

    def get(self, name) -> Type:
        cached = self.cache.get(name)
        if cached is not None:
            return cached
        definition = self.definitions.get(name)
        if definition is None:
            raise ConfigError('unknown type name ' + repr(name))
        kind = definition['kind']
        if kind == 'bool':
            node = Bool(name)
        elif kind == 'char':
            node = Char(name)
        elif kind == 'int':
            node = Int(definition['bits'], name)
        elif kind == 'string':
            node = String(definition['maxsize'], name)
        elif kind == 'void':
            node = Void(name)
        elif kind == 'enum':
            node = Enum(name, definition['values'])
        elif kind == 'array':
            node = Array(None, definition['size'], name)
            node.element_type = self.get(definition['element'])
        elif kind == 'struct':
            node = Struct(name, {})
            fields = {}
            for (field_name, field_type) in definition['fields']:
                fields[field_name] = self.get(field_type)
            node.fields = fields
        elif kind == 'alias':
            node = Alias(name, None)
            node.type = self.get(definition['target'])
        else:
            raise ConfigError('unknown type kind ' + repr(kind))
        self.cache[name] = node
        return node


def convert_constant(node_type, value):
    """The JSON value representation of a typed constant (never truncated)."""
    inner = Type.inner(node_type)
    if isinstance(inner, Bool):
        return bool(value)
    if isinstance(inner, Char):
        return value
    if isinstance(inner, Int):
        return value
    if isinstance(inner, String):
        return value
    if isinstance(inner, Enum):
        return value
    if isinstance(inner, Array):
        element = inner.element_type
        return [convert_constant(element, item) for item in value]
    if isinstance(inner, Struct):
        fields = inner.fields
        return {name: convert_constant(fields[name], value[name]) for name in fields}
    return None


class PredicateCompiler(object):
    """Compile campaign predicate JSON into the typed expression AST."""

    __slots__ = ('types',)

    def __init__(self, types: TypeTable):
        self.types = types

    def predicate(self, source, scope):
        if source is None:
            return Predicate(None)
        return Predicate(self.compile(source, scope))

    def compile(self, node, scope):
        head = node[0]
        if head == 'var':
            name = node[1]
            return Var(scope[name], name)
        if head == 'const':
            node_type = self.types.get(node[1])
            return Const(node_type, convert_constant(node_type, node[2]))
        if head == 'field':
            operand = self.compile(node[1], scope)
            inner = Type.inner(operand.type)
            name = node[2]
            return Field(inner.fields[name], operand, name)
        if head == 'index':
            operand = self.compile(node[1], scope)
            inner = Type.inner(operand.type)
            index = node[2]
            return Index(inner.element_type, operand, index)
        if head == 'all':
            binding = node[1]
            operand = self.compile(node[2], scope)
            inner = Type.inner(operand.type)
            inner_scope = dict(scope)
            inner_scope[binding] = inner.element_type
            body = self.compile(node[3], inner_scope)
            return Forall(Bool(), operand, body, binding)
        if head == 'match':
            operand = self.compile(node[1], scope)
            return Match(Bool(), operand, compile_pattern(node[2]))
        if head == 'not':
            return Not(Bool(), self.compile(node[1], scope))
        operation = canonical_op(head)
        if operation in BINOPS:
            left = self.compile(node[1], scope)
            right = self.compile(node[2], scope)
            if operation in ('add', 'sub'):
                node_type = Type.inner(left.type)
                if not isinstance(node_type, Int):
                    node_type = Type.inner(right.type)
                return Binop(node_type, operation, left, right)
            return Binop(Bool(), operation, left, right)
        raise ConfigError('unknown expression form ' + repr(head))


class ModuleModel(object):
    __slots__ = ('name', 'params', 'param_names', 'result_name', 'result_type',
                 'requires', 'scope')

    def __init__(self, name, params, result_name, result_type, requires, scope):
        self.name = name
        self.params = params
        self.param_names = [name for (name, _) in params]
        self.result_name = result_name
        self.result_type = result_type
        self.requires = requires
        self.scope = scope


class PipeModel(object):
    __slots__ = ('target', 'filter', 'bind')

    def __init__(self, target, filter_name, bind):
        self.target = target
        self.filter = filter_name
        self.bind = tuple(bind.items())


class Application(object):
    """One composed filter application: a filter plus its own binding."""

    __slots__ = ('module', 'parent_env', 'mapping', 'env', 'predicate')

    def __init__(self, module, parent_env, bind):
        self.module = module
        self.parent_env = parent_env
        self.mapping = bind
        self.env = {}
        self.predicate = module.requires

    def evaluate(self):
        env = self.env
        parent = self.parent_env
        for (name, source) in self.mapping:
            env[name] = parent[source]
        return self.predicate.evaluate(env)


class EntryContext(object):
    __slots__ = ('name', 'module', 'layout', 'plan', 'apps', 'env', 'requires',
                 'state_param', 'message_param')

    def accepts(self):
        """NOT(all bound filters accept, transitively) drives ``bad_input``."""
        for application in self.apps:
            if not application.evaluate():
                return False
        return True


class MachineModel(object):
    __slots__ = ('states', 'index', 'initial', 'state_param', 'message_param',
                 'graph', 'preparer', 'sources', 'closures', 'compiler', 'scope')

    def __init__(self, document, compiler, scope):
        self.states = list(document['states'])
        self.index = {name: position for position, name in enumerate(self.states)}
        self.initial = document['initial']
        self.state_param = document['state_param']
        self.message_param = document['message_param']
        self.compiler = compiler
        self.scope = scope
        edges = []
        sources = []
        for transition in document['transitions']:
            when = transition['when']
            if when is None:
                guard = -1
            else:
                guard = len(sources)
                sources.append(when)
            edges.append((transition['from'], transition['to'], transition['cost'],
                          transition['command'], guard))
        self.sources = sources
        self.closures = [None] * len(sources)
        self.graph = MachineGraph(self.states, self.initial, edges)
        self.preparer = self.graph.preparer()

    def guard(self, position):
        compiled = self.closures[position]
        if compiled is None:
            compiled = self.compiler.predicate(self.sources[position], self.scope)
            self.closures[position] = compiled
        return compiled

    def mask(self, env):
        sources = self.sources
        count = len(sources)
        if count == 0:
            return _EMPTY_MASK
        result = bytearray(count)
        for position in range(count):
            if self.guard(position).evaluate(env):
                result[position] = 1
        return bytes(result)


class Campaign(object):
    """The compiled campaign plus its replay driver."""

    def __init__(self, document):
        if not isinstance(document, dict):
            raise ConfigError('campaign must be a JSON object')
        self.types = TypeTable(document.get('types') or [])
        self.compiler = PredicateCompiler(self.types)
        self.modules = {}
        for item in document.get('modules') or []:
            self.modules[item['name']] = self._module(item)
        self.graph = DependencyGraph()
        for name in self.modules:
            self.graph.add_node(name)
        for (caller, callee) in document.get('calls') or []:
            self.graph.CallEdge(caller, [callee])
        self.pipes_by_target = {}
        for item in document.get('pipes') or []:
            pipe = PipeModel(item['target'], item['filter'], item['bind'])
            self.pipes_by_target.setdefault(pipe.target, []).append(pipe)
            self.graph.CallEdge(pipe.target, [pipe.filter])
        self.entries = list(document.get('entries') or [])
        self.runs = list(document.get('runs') or [])
        machine = document.get('machine')
        self.machine = None if machine is None else MachineModel(
            machine, self.compiler, self._guard_scope())
        self.contexts = []
        self.context_by_entry = {}
        for name in self.entries:
            context = self._context(name)
            self.contexts.append(context)
            self.context_by_entry[name] = context
        self._mask_cache = {}

    # -- compilation ----------------------------------------------------
    def _module(self, item):
        params = [(name, self.types.get(type_name))
                  for (name, type_name) in item['params']]
        scope = {name: node_type for (name, node_type) in params}
        result_name, result_type_name = item['result']
        result_type = self.types.get(result_type_name)
        requires = self.compiler.predicate(item['requires'], scope)
        return ModuleModel(item['name'], params, result_name, result_type,
                           requires, scope)

    def _guard_scope(self):
        """Guards are well typed for every entry: union the entry scopes."""
        scope = {}
        for name in self.entries:
            module = self.modules[name]
            for (parameter, parameter_type) in module.params:
                scope.setdefault(parameter, parameter_type)
        return scope

    def _declarations(self, order):
        """Declaration names in dependency-before-user postorder."""
        emitted = []
        seen = set()
        done = set()

        def record(name):
            if name not in seen:
                seen.add(name)
                emitted.append(name)

        def walk(node_type):
            if isinstance(node_type, Alias):
                if id(node_type) in done:
                    return
                walk(node_type.type)
                record(node_type.name)
                done.add(id(node_type))
            elif isinstance(node_type, Struct):
                if id(node_type) in done:
                    return
                for field in node_type.fields.values():
                    walk(field)
                record(node_type.name)
                done.add(id(node_type))
            elif isinstance(node_type, Enum):
                record(node_type.name)
            elif isinstance(node_type, Array):
                walk(node_type.element_type)

        for name in order:
            module = self.modules[name]
            for (_parameter, parameter_type) in module.params:
                walk(parameter_type)
            walk(module.result_type)
        return emitted

    def _context(self, name):
        module = self.modules[name]
        order = self.graph.compile_order(name)
        declarations = self._declarations(order)
        pipes = self.pipes_by_target.get(name)
        layout = HarnessLayout(module.params,
                               (module.result_name, module.result_type),
                               bool(pipes))
        plan = {
            'entry': name,
            'modules': order,
            'types': declarations,
            'slots': layout.slots,
            'flag': layout.flag,
            'variables': layout.variables,
        }
        context = EntryContext()
        context.name = name
        context.module = module
        context.layout = layout
        context.plan = plan
        context.env = {}
        context.requires = module.requires
        machine = self.machine
        if machine is None:
            context.state_param = None
            context.message_param = None
        else:
            context.state_param = machine.state_param
            context.message_param = machine.message_param
        context.apps = self._applications(module, context.env)
        return context

    def _applications(self, module, env):
        """Every composed pipe application of an entry, parents first."""
        applications = []
        queue = deque([(module, env)])
        while queue:
            current, parent_env = queue.popleft()
            for pipe in self.pipes_by_target.get(current.name, ()):
                target = self.modules[pipe.filter]
                application = Application(target, parent_env, pipe.bind)
                applications.append(application)
                queue.append((target, application.env))
        return applications

    # -- replay ---------------------------------------------------------
    def run(self):
        plans = [context.plan for context in self.contexts]
        records = []
        corpus = Corpus()
        machine = self.machine
        append = records.append
        for index, item in enumerate(self.runs):
            context = self.context_by_entry.get(item['entry'])
            if context is None:
                append({'status': INVALID_TEST})
                continue
            layout = context.layout
            try:
                objects = wire.decode(item['ktest'])
                leaves, flag = layout.decode(objects)
            except (wire.TransportError, InventoryError, ValueError, TypeError,
                    KeyError, AttributeError):
                append({'status': INVALID_TEST})
                continue
            inputs, result = layout.values(leaves)
            env = context.env
            for name, value in inputs.items():
                env[name] = value
            accepted = context.accepts()
            if layout.flag is not None and flag != (0 if accepted else 1):
                append({'status': INVALID_TEST})
                continue
            if not accepted or not context.requires.evaluate(env):
                append({'status': FILTERED})
                continue
            if machine is None:
                cost = 0
                commands = ()
            else:
                key = corpus_key(context.name, inputs)
                mask = self._mask_cache.get(key)
                if mask is None:
                    mask = machine.mask(env)
                    if len(self._mask_cache) >= 4096:
                        self._mask_cache.clear()
                    self._mask_cache[key] = mask
                prepared = machine.preparer.prepare(
                    mask, machine.index[inputs[context.state_param]])
                if prepared is None:
                    append({'status': UNREACHABLE})
                    continue
                cost, preamble = prepared
                commands = list(preamble)
                commands.append(inputs[context.message_param])
                case, fresh = corpus.intern(key, context.name, inputs, cost,
                                            commands, index)
                append({'status': READY if fresh else DUPLICATE, 'case': case,
                        'model_result': result})
                continue
            key = corpus_key(context.name, inputs)
            case, fresh = corpus.intern(key, context.name, inputs, cost,
                                        commands, index)
            append({'status': READY if fresh else DUPLICATE, 'case': case,
                    'model_result': result})
        return {'plans': plans, 'records': records, 'corpus': corpus.rows}


def execute(campaign):
    """Compile and replay one campaign, returning its JSON certificate."""
    return Campaign(campaign).run()
